"""Render a deterministic, offline benchmark explorer from recorded result JSON.

No benchmark execution, model calls, remote assets, or application data access.
The JSON script payload escapes '<' so untrusted source text cannot end the tag.
"""
from __future__ import annotations
import argparse
import csv
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def read_json(path, optional=False):
    if optional and not path.exists():
        return None
    return json.loads(path.read_text())


def collect_data(input_dir, fixture_path, scifact_dir):
    sci = read_json(input_dir / 'scifact-results.json')
    temporal = read_json(input_dir / 'temporal-results.json')
    light = read_json(input_dir / 'lightrag-results.json', optional=True)
    filtered_light = read_json(input_dir / 'lightrag-filtered-results.json', optional=True)
    fixture = read_json(fixture_path)
    runs = {name: read_json(input_dir / f'scifact-{name}.run.json', optional=True) or {} for name in sci['methods']}
    runs = {name: value.get('rankings', value) for name, value in runs.items()}
    query_text, qrels, titles = {}, {}, {}
    if (scifact_dir / 'queries.jsonl').exists():
        query_text = {str(row['_id']): row['text'] for row in map(json.loads, (scifact_dir / 'queries.jsonl').read_text().splitlines())}
    if (scifact_dir / 'qrels/test.tsv').exists():
        with (scifact_dir / 'qrels/test.tsv').open() as source:
            for row in csv.DictReader(source, delimiter='\t'):
                if int(row['score']) > 0:
                    qrels.setdefault(row['query-id'], []).append(row['corpus-id'])
    needed = {aid for run in runs.values() for ranked in run.values() for aid in ranked}
    needed.update(aid for gold in qrels.values() for aid in gold)
    if (scifact_dir / 'corpus.jsonl').exists():
        with (scifact_dir / 'corpus.jsonl').open() as source:
            for line in source:
                row = json.loads(line)
                if str(row['_id']) in needed:
                    titles[str(row['_id'])] = row['title']
    sci_cases = [{**row, 'id': row['query_id'], 'query': query_text.get(row['query_id'], f"Query {row['query_id']} (text unavailable)"),
                  'gold': qrels.get(row['query_id']), 'rankings': {name: run.get(row['query_id'], []) for name, run in runs.items()}}
                 for row in sci['per_query']]
    return {'scifact': sci, 'temporal': temporal, 'lightrag': light,
            'lightrag_filtered': filtered_light, 'scifact_cases': sci_cases, 'scifact_titles': titles,
            'temporal_cases': fixture['queries'],
            'assertions': {row['id']: row for row in fixture['assertions']},
            'input_hashes': {path.name: hashlib.sha256(path.read_bytes()).hexdigest()
                             for path in [input_dir / 'scifact-results.json', input_dir / 'temporal-results.json', input_dir / 'lightrag-results.json', input_dir / 'lightrag-filtered-results.json', fixture_path]
                             if path.exists()}}


