JS = r'''
const DATA=JSON.parse(document.getElementById('benchmark-data').textContent);
const labels={bm25:'BM25',dense_minilm:'Dense MiniLM',rrf_bm25_dense:'RRF · BM25 + dense',chronoverse_store_optimized_cache:'Chronoverse · document-cache adaptation'};
const CHRONO='chronoverse_store_optimized_cache';
let track='scifact',chartMetric='ndcg@10',caseLimit=25;
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const num=(v,d=4)=>Number.isFinite(v)?v.toFixed(d):'—',pct=v=>Number.isFinite(v)?(v*100).toFixed(1)+'%':'—',ms=v=>Number.isFinite(v)?(v*1000).toFixed(v<.001?3:2)+' ms':'—';
const label=name=>labels[name]||name;
function safeUrl(url){try{const parsed=new URL(url);return ['https:','http:'].includes(parsed.protocol)?url:null;}catch{return null;}}
function details(title,data){return `<details class="protocol-details"><summary>${esc(title)}</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details>`;}
function card(title,value,note){return `<div class="card"><span>${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`;}
function systemRows(){if(track==='scifact')return Object.entries(DATA.scifact.methods).map(([name,row])=>({name,metrics:row.metrics,latency:row.warm_latency}));if(track==='temporal')return Object.entries(DATA.temporal.systems).map(([name,row])=>({name,metrics:row.summary,latency:row.summary.latency}));return DATA.lightrag?[{name:'LightRAG · custom KG',metrics:DATA.lightrag.summary.temporal_capability_at_10,latency:DATA.lightrag.summary.temporal_capability_at_10.latency},...(DATA.lightrag_filtered?[{name:DATA.lightrag_filtered.method,metrics:DATA.lightrag_filtered.summary,latency:null}]:[])]:[];}
function performanceTable(rows,temporal=false){let keys=temporal?['ndcg@10','hit@1','recall@10','empty_gold_abstention_rate','returned_set_precision@10_answerable','coordinate_ineligible_fraction@10']:['ndcg@10','recall@5','recall@10','mrr@10','hit@1'];const names={'empty_gold_abstention_rate':'Empty-gold abstention ↑','returned_set_precision@10_answerable':'Returned-set precision ↑','coordinate_ineligible_fraction@10':'Coordinate-ineligible ↓'};return `<div class="table-wrap"><table><thead><tr><th>System</th>${keys.map(key=>`<th class="number">${esc(names[key]||key)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr class="${row.name.toLowerCase().includes('chronoverse')?'chrono':''}"><td>${esc(label(row.name))}</td>${keys.map(key=>`<td class="number">${num(row.metrics[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function chartPanel(){return `<section class="panel"><div class="panel-heading"><div><h3>${track==='scifact'?'Relevant evidence retrieval':'First-result and ranking diagnostics'}</h3><p>${track==='scifact'?'All 300 public test queries. Higher is better.':'Answerable queries only. Empty answers are evaluated separately.'}</p></div><div class="metric-picker" aria-label="Chart metric"><button data-metric="ndcg@10" class="${chartMetric==='ndcg@10'?'active':''}">nDCG@10</button><button data-metric="hit@1" class="${chartMetric==='hit@1'?'active':''}">Hit@1</button></div></div><div id="bars" class="bar-chart"></div><div class="bar-axis"><span>0.00</span><span>0.25</span><span>0.50</span><span>0.75</span><span>1.00</span></div>${performanceTable(systemRows(),track!=='scifact')}<p class="metric-note">${track==='scifact'?'nDCG measures ranking quality against relevance judgments. SciFact relevance does not tell us whether a claim is true.':'A perfect hit rate or nDCG can coexist with many extra records. Returned-set precision and empty-gold abstention expose that limitation; extra retrieved context is not itself a generated false answer.'}</p></section>`;}
function renderBars(){const rows=systemRows().sort((a,b)=>(b.metrics[chartMetric]||0)-(a.metrics[chartMetric]||0));$('bars').innerHTML=rows.map(row=>`<div class="bar-row ${row.name.toLowerCase().includes('chronoverse')?'chrono':''}"><div class="bar-label">${esc(label(row.name))}</div><div class="bar-track" role="img" aria-label="${esc(label(row.name))}: ${esc(chartMetric)} ${num(row.metrics[chartMetric])}"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,(row.metrics[chartMetric]||0)*100))}%"></div></div><span class="bar-value">${num(row.metrics[chartMetric])}</span></div>`).join('');}
function latencyTable(rows){return `<div class="table-wrap"><table><thead><tr><th>System / measured pipeline</th><th class="number">Warm p50</th><th class="number">Warm p95</th><th class="number">Samples</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(label(row.name))}</td><td class="number">${ms(row.latency?.p50_seconds)}</td><td class="number">${ms(row.latency?.p95_seconds)}</td><td class="number">${esc(row.latency?.samples??'—')}</td></tr>`).join('')}</tbody></table></div>`;}
function scientific(){const s=DATA.scifact,c=s.methods[CHRONO],ci=s.paired_bootstrap_ndcg_difference?.rrf_bm25_dense;return `<div class="track-title"><div><h2>Can it retrieve relevant scientific evidence?</h2><p>The full BEIR SciFact corpus and official test relevance judgments, with identical canonical record text for all four methods.</p></div><a class="download" href="scifact-results.json" download>↓ SciFact results JSON</a></div><div class="cards">${card('Indexed scientific abstracts',s.indexed_count.toLocaleString(),'Complete BEIR SciFact corpus')}${card('Public test queries',s.test_query_count,'Held-out relevance judgments')}${card('Chronoverse nDCG@10',num(c.metrics['ndcg@10']),'Document-cache adaptation; scorer unchanged')}</div><div class="notice"><strong>Numerically higher is not a demonstrated win over RRF.</strong> ${ci?`The paired nDCG difference is ${num(ci.mean_difference)}, with a descriptive 95% bootstrap interval [${num(ci.ci95_low)}, ${num(ci.ci95_high)}]. ${ci.ci95_low<=0&&ci.ci95_high>=0?'The interval crosses zero.':'The interval excludes zero in this query resampling analysis.'}`:'Paired uncertainty results are unavailable.'} This is one dataset, not a general superiority claim.</div>${chartPanel()}<section class="panel"><div class="panel-heading"><div><h3>Uncertainty in the ranking difference</h3><p>Chronoverse minus each comparator; positive favors Chronoverse on this test set.</p></div></div><div class="table-wrap"><table><thead><tr><th>Comparator</th><th class="number">Mean Δ nDCG@10</th><th class="number">95% interval</th><th>Interpretation</th></tr></thead><tbody>${Object.entries(s.paired_bootstrap_ndcg_difference||{}).map(([name,row])=>`<tr><td>${esc(label(name))}</td><td class="number">${num(row.mean_difference)}</td><td class="number">[${num(row.ci95_low)}, ${num(row.ci95_high)}]</td><td>${row.ci95_low<=0&&row.ci95_high>=0?'Includes zero':'Excludes zero in this resampling'}</td></tr>`).join('')}</tbody></table></div><p class="metric-note">${esc(s.bootstrap_note)}</p></section><section class="panel"><div class="panel-heading"><div><h3>The performance cost is still substantial.</h3><p>Within this SciFact protocol only. Document embeddings are cached; each query embedding is fresh.</p></div></div>${latencyTable(systemRows())}<div class="notice"><strong>These full-run Chronoverse times are not stock application latency.</strong> The stock ${esc(s.stock_pilot.production_cache_size)}-entry embedding cache is smaller than the ${esc(s.indexed_count)}-document corpus. The actual stock pilot took ${s.stock_pilot.rows.map(row=>num(row.seconds,2)+' s').join(' and ')} per query (${s.stock_pilot.rows.length} samples). First sample includes model initialization; this is too little data for a stable p95. The full run changed only document-cache capacity inside the benchmark process.</div><p class="subtext">${esc(s.parameters.chronoverse.only_optimization)}. Cache equivalence was checked on ${s.cache_equivalence.length} pilot queries; ${s.cache_equivalence.every(row=>row.exact_top10_ids&&row.exact_scores)?'their top-10 IDs and scores matched exactly':'inspect the raw equivalence checks'}.</p>${details('Indexing time, warm timing accounting, and runtime',{index_timings:s.index_timings,timing_accounting:s.timing_accounting,environment:s.environment})}</section><section class="panel"><h3>What this experiment does not establish</h3><ul class="caveats" style="margin-top:15px">${s.limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>${details('Exact retrieval configuration and canonical text',{parameters:s.parameters,canonical_text:s.canonical_text})}</section>`;}
function temporal(){const t=DATA.temporal,c=t.systems['Chronoverse stock'].summary;return `<div class="track-title"><div><h2>Does supplied temporal context change the answer?</h2><p>Generated assertions, lifecycle events, and query coordinates. This tests explicit filtering capability, not extraction, general reasoning, or a public leaderboard.</p></div><a class="download" href="temporal-results.json" download>↓ Temporal results JSON</a></div><div class="cards">${card('Manually specified scenario designs',t.scenario_templates,`${t.entity_instantiations} renamed entity instantiations per design`)}${card('Answerable / empty-gold queries',`${c.query_count} / ${c.empty_gold_count}`,`${t.corpus_size} assertions; exact query wording`)}${card('Chronoverse empty-gold abstention',pct(c.empty_gold_abstention_rate),'Returning unrelated context is not abstention')}</div><div class="notice info"><strong>Temporal filtering is useful, but not unique to Chronoverse.</strong> The three reference-filtered BM25/dense/RRF comparators and Chronoverse all reach ${pct(c['hit@1'])} hit@1 on answerable questions here. The comparators receive the same explicit metadata and lifecycle events. Their filters are engineered reference implementations, not native BM25 features.</div>${chartPanel()}<div class="notice"><strong>The empty-answer gap remains.</strong> ${c.empty_gold_count} queries have no relevant target assertion. Chronoverse’s abstention rate is ${pct(c.empty_gold_abstention_rate)}; a coordinate-valid result may still be unrelated to the requested entity and predicate. Hit@1 alone does not measure this failure.</div><section class="panel"><h3>Temporal metrics, beyond a first correct hit</h3><p class="subtext">Answerable precision excludes empty gold. Exact-set correctness includes all queries and penalizes extra records; it is stricter than context retrieval.</p><div class="table-wrap"><table><thead><tr><th>System</th><th class="number">Exact set@10 ↑</th><th class="number">Queries with scope violations ↓</th><th class="number">Empty-gold abstention ↑</th></tr></thead><tbody>${systemRows().map(row=>`<tr><td>${esc(row.name)}</td><td class="number">${pct(row.metrics['exact_set@10_all_queries'])}</td><td class="number">${pct(row.metrics['queries_with_coordinate_violation@10'])}</td><td class="number">${pct(row.metrics.empty_gold_abstention_rate)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h3>Warm timings on this small temporal corpus</h3><p class="subtext">${esc(t.latency_note)} These measurements must not be compared directly with SciFact’s fresh-query-encoding pipeline.</p>${latencyTable(systemRows())}${details('Temporal run protocol and indexing',{protocol:t.protocol,scope_filter_note:t.scope_filter_note,latency_note:t.latency_note,repeats:t.repeats,indexing_seconds:t.indexing_seconds,model:t.model,versions:t.versions})}</section><section class="panel"><h3>Coverage limits</h3><ul class="caveats" style="margin-top:15px"><li>${t.queries} queries are ${t.scenario_templates} scenario templates repeated across ${t.entity_instantiations} renamed entities, not ${t.queries} independently designed scenarios.</li><li>Queries repeat exact entity and predicate wording. This does not test difficult paraphrases, multi-hop questions, or ingestion quality.</li><li>Missing cases include chained corrections, delayed supersession, late evidence, fractional timestamps, timezone boundaries, and exact correction/retraction knowledge boundaries.</li><li>All systems are retrieval-only. No answer generator or LLM judge converts the returned context into claims.</li></ul></section>`;}
function light(){const l=DATA.lightrag;if(!l)return `<div class="pending"><h3>LightRAG run pending</h3><p>No result JSON was present when this report was generated. No scores or timing estimates have been substituted. Regenerate after the actual run completes.</p></div>`;const m=l.summary.temporal_capability_at_10;return `<div class="track-title"><div><h2>An actual graph-retrieval library, under a bounded protocol.</h2><p>LightRAG ${esc(l.implementation.version)} over a caller-supplied knowledge graph and the same synthetic assertion texts. This is retrieval context, not end-to-end GraphRAG.</p></div><a class="download" href="lightrag-results.json" download>↓ LightRAG results JSON</a></div><div class="cards">${card('Real implementation',`LightRAG ${l.implementation.version}`,'ainsert_custom_kg → aquery_data')}${card('Answerable hit@1',pct(m['hit@1']),`${m.query_count} answerable queries; top-10 evaluation`)}${card('LLM calls / generated answers',`${l.implementation.llm_calls} / ${l.implementation.answer_generation?'enabled':'none'}`,'Supplied keywords; local MiniLM embeddings')}</div><div class="notice"><strong>Interpret the representation before the score.</strong> ${esc(l.fixture.events_not_ingested_as_temporal_policy)} lifecycle events were not installed as an executable temporal policy. A supplied assertion hub graph preserves parallel provenance. This measures the configured LightRAG context-retrieval pipeline, not its maximum attainable performance or equivalence to Microsoft GraphRAG.</div>${DATA.lightrag_filtered?`<div class="notice info"><strong>A capable filter adapter is shown separately.</strong> ${esc(DATA.lightrag_filtered.protocol)} Its answerable hit@1 is ${pct(DATA.lightrag_filtered.summary['hit@1'])}; empty-gold abstention is ${pct(DATA.lightrag_filtered.summary.empty_gold_abstention_rate)}. It is an engineered adapter, not native LightRAG policy support.</div>`:''}${chartPanel()}<section class="panel"><h3>Measured LightRAG pipeline only</h3><p class="subtext">${esc(l.track)}. No extraction, reranking, generation, or remote model calls. Native retrieval requests 20 candidate chunks; the report evaluates the first 10. Fresh keyword/query embeddings are included per call, while the temporal comparators warm all query embeddings. These latencies are not a fair direct race. No adapter-inclusive latency was measured.</p><div class="cards">${card('KG build',num(l.timing.kg_build_seconds,3)+' s','Separate from query timings')}${card('Warm p50',num(l.timing.warm_latency_p50_ms,2)+' ms',`${l.timing.warm_query_samples} warm samples`)}${card('Warm p95',num(l.timing.warm_latency_p95_ms,2)+' ms','Local shared-machine measurement')}</div>${details('Implementation, representation, and timings',{implementation:l.implementation,representation:l.representation,timing:l.timing,post_filter:DATA.lightrag_filtered?{protocol:DATA.lightrag_filtered.protocol,latency_note:DATA.lightrag_filtered.latency_note}:null})}</section><section class="panel"><h3>Limits and excluded systems</h3><ul class="caveats" style="margin-top:15px">${l.limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>${details('Why other graph systems were not run',l.other_systems)}</section>`;}
function allCases(){if(track==='scifact')return DATA.scifact_cases;if(track==='lightrag'&&!DATA.lightrag)return [];return DATA.temporal_cases;}
function namesForCases(){if(track==='scifact')return Object.keys(DATA.scifact.methods);const names=Object.keys(DATA.temporal.systems);if(DATA.lightrag)names.push('LightRAG · custom KG');if(DATA.lightrag_filtered)names.push(DATA.lightrag_filtered.method);return names;}
function ranks(row,name){if(track==='scifact')return row.rankings[name]||[];if(DATA.lightrag_filtered&&name===DATA.lightrag_filtered.method)return DATA.lightrag_filtered.rankings[row.id]||[];if(name==='LightRAG · custom KG')return DATA.lightrag?.queries.find(item=>item.id===row.id)?.retrieved_assertion_ids.slice(0,10)||[];return DATA.temporal.systems[name]?.rankings[row.id]||[];}
function gold(row){return track==='scifact'?row.gold:row.gold_assertion_ids;}
function rowMetric(row,name){if(track==='scifact')return row.metrics[name]?.[chartMetric]??0;const g=gold(row)||[],list=ranks(row,name).slice(0,10);if(!g.length)return null;if(chartMetric==='hit@1')return g.includes(list[0])?1:0;const dcg=list.reduce((sum,id,index)=>sum+(g.includes(id)?1/Math.log2(index+2):0),0),ideal=Array.from({length:Math.min(g.length,10)},(_,index)=>1/Math.log2(index+2)).reduce((a,b)=>a+b,0);return ideal?dcg/ideal:0;}
function failureExplorer(){if(track==='lightrag'&&!DATA.lightrag)return '';const names=namesForCases(),a=track==='scifact'?CHRONO:track==='lightrag'?'LightRAG · custom KG':'Chronoverse stock',b=track==='scifact'?'rrf_bm25_dense':track==='lightrag'?(DATA.lightrag_filtered?DATA.lightrag_filtered.method:'Chronoverse stock'):'BM25';const options=selected=>names.map(name=>`<option value="${esc(name)}"${name===selected?' selected':''}>${esc(label(name))}</option>`).join('');return `<section class="panel"><h3>Inspect disagreements and failure cases</h3><p class="subtext">Compare actual top-10 record IDs for the same query. Green denotes judged relevance, not truth. ${track==='scifact'?'Scientific titles and judgments come from the downloaded BEIR corpus.':'Scope coordinates and fixed gold come from the independent synthetic fixture; comparison does not imply identical library pipelines.'}</p><div class="controls"><label>System A<select id="system-a">${options(a)}</select></label><label>System B<select id="system-b">${options(b)}</select></label><label>Show<select id="case-filter"><option value="different">Ranking metric differs</option><option value="a-loses">A scores lower</option><option value="b-loses">B scores lower</option><option value="both-miss">Both miss top result</option>${track!=='scifact'?'<option value="empty">Empty gold, nonempty retrieval</option>':''}<option value="all">All queries</option></select></label><label class="wide">Find query or category<input id="case-search" type="search" placeholder="Search text, category, or ID…"/></label></div><p id="case-count" class="failure-count" aria-live="polite"></p><div id="cases"></div><button id="more-cases" class="more-button">Show 25 more</button></section>`;}
function rankingMarkup(row,name){const ids=ranks(row,name).slice(0,10),g=gold(row);return `<div class="ranking"><h4>${esc(label(name))}</h4>${ids.length?`<ol>${ids.map(id=>{const assertion=DATA.assertions[id],title=track==='scifact'?DATA.scifact_titles[id]:(assertion?`${assertion.subject} ${assertion.predicate} ${assertion.object}`:null),relevant=g?.includes(id);return `<li class="${relevant?'relevant':''}"><strong>${esc(id)}</strong>${relevant?'<span class="gold-tag">GOLD</span>':''}${title?`<small>${esc(title)}</small>`:''}</li>`;}).join('')}</ol>`:'<p class="subtext">No records returned.</p>'}</div>`;}
function renderCases(){if(!$('cases'))return;const a=$('system-a').value,b=$('system-b').value,filter=$('case-filter').value,text=$('case-search').value.toLowerCase().trim();let rows=allCases().filter(row=>{const g=gold(row),va=rowMetric(row,a),vb=rowMetric(row,b);if(text&&!`${row.id} ${row.query} ${row.category||''}`.toLowerCase().includes(text))return false;if(filter==='empty')return g?.length===0&&(ranks(row,a).length||ranks(row,b).length);if(filter==='all')return true;if(!g?.length)return false;if(filter==='both-miss')return !g.includes(ranks(row,a)[0])&&!g.includes(ranks(row,b)[0]);if(filter==='a-loses')return va<vb-1e-9;if(filter==='b-loses')return vb<va-1e-9;return Math.abs(va-vb)>1e-9;});rows.sort((x,y)=>{const dx=Math.abs((rowMetric(x,a)||0)-(rowMetric(x,b)||0)),dy=Math.abs((rowMetric(y,a)||0)-(rowMetric(y,b)||0));return dy-dx||String(x.id).localeCompare(String(y.id),undefined,{numeric:true});});$('case-count').textContent=`${rows.length} matching queries · showing ${Math.min(caseLimit,rows.length)} · metric: ${chartMetric}. Empty-gold queries have no ranking metric.`;$('cases').innerHTML=rows.slice(0,caseLimit).map(row=>{const g=gold(row),va=rowMetric(row,a),vb=rowMetric(row,b);return `<details class="case"><summary><div class="case-text">${esc(row.query)}<small>${esc(row.id)}${row.category?' · '+esc(row.category.replaceAll('_',' ')):''}</small></div><span class="case-delta">A ${num(va,3)} / B ${num(vb,3)}</span></summary><div class="case-body"><div class="case-meta"><strong>Gold:</strong> ${g===null?'Judgments unavailable in local data':g.length?esc(g.join(', ')):'∅ — no relevant target assertion'}${row.scope?`<br/><strong>Coordinates:</strong> ${esc(JSON.stringify(row.scope))}`:''}</div><div class="rankings">${rankingMarkup(row,a)}${rankingMarkup(row,b)}</div></div></details>`;}).join('')||'<div class="empty-state">No cases match this filter. Choose “All queries” or compare another pair of systems.</div>';$('more-cases').hidden=rows.length<=caseLimit;}
function sources(){const input=track==='scifact'?DATA.scifact:track==='temporal'?DATA.temporal:DATA.lightrag;let links=track==='scifact'?Object.entries(DATA.scifact.sources).map(([name,url])=>({title:name.replaceAll('_',' '),url})):track==='lightrag'&&input?input.sources:[];return `<section class="panel"><h3>Sources, data, and reproducibility</h3><div class="source-grid">${links.map(item=>safeUrl(item.url)?`<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a>`:`<span>${esc(item.url||item.title)}</span>`).join('')}<a href="scifact-results.json" download>SciFact result JSON</a><a href="temporal-results.json" download>Temporal result JSON</a>${DATA.lightrag?'<a href="lightrag-results.json" download>LightRAG result JSON</a>':''}${DATA.lightrag_filtered?'<a href="lightrag-filtered-results.json" download>LightRAG reference post-filter JSON</a>':''}<a href="temporal-fixture.json" download>Synthetic fixture and fixed gold</a><a href="README.md">Benchmark method and reproduction notes</a></div><p class="subtext">Result files are local artifacts. The report needs no network access; source links open only when selected. Relevance labels were not used to tune retrieval parameters.</p>${details('Input hashes and artifact timestamps',{sha256:DATA.input_hashes,scifact_created_at:DATA.scifact.created_at,temporal_created_at:DATA.temporal.created_at,lightrag_created_at:DATA.lightrag?.created_at??null})}</section>`;}
function render(){caseLimit=25;document.querySelectorAll('[data-track]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.track===track)));$('content').innerHTML=(track==='scifact'?scientific():track==='temporal'?temporal():light())+failureExplorer()+sources();if($('bars'))renderBars();document.querySelectorAll('[data-metric]').forEach(button=>button.addEventListener('click',()=>{chartMetric=button.dataset.metric;document.querySelectorAll('[data-metric]').forEach(item=>item.classList.toggle('active',item.dataset.metric===chartMetric));renderBars();caseLimit=25;renderCases();}));for(const id of ['system-a','system-b','case-filter','case-search'])if($(id))$(id).addEventListener(id==='case-search'?'input':'change',()=>{caseLimit=25;renderCases();});if($('more-cases'))$('more-cases').addEventListener('click',()=>{caseLimit+=25;renderCases();});renderCases();}
document.querySelectorAll('[data-track]').forEach(button=>button.addEventListener('click',()=>{track=button.dataset.track;chartMetric=track==='scifact'?'ndcg@10':'hit@1';render();}));
$('created').textContent=`Recorded ${DATA.scifact.created_at.slice(0,10)} · local CPU runs`;
render();
'''


def render(data):
    payload = json.dumps(data, ensure_ascii=False, sort_keys=True, separators=(',', ':')).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026').replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Chronoverse · Comparative retrieval benchmarks</title><style>''' + CSS + '''</style></head><body><header><div><a class="brand" href="#">chronoverse<span>BENCHMARK LAB</span></a><span class="local"><i class="dot"></i> Local evidence · no generated answers</span></div></header><main><section class="intro"><div class="eyebrow">RETRIEVAL, UNDER EXAMINATION</div><h1>Measure the evidence.<br>Keep the limits.</h1><p>Three experiments answer different questions: public evidence retrieval, explicit temporal filtering, and an actual graph-retrieval library. Inspect the results, their costs, and the queries each system misses.</p><div class="intro-meta"><span id="created">Recorded local measurements</span><span>No paid inference</span><span>No LLM judge</span><span>Self-contained report</span></div></section><nav class="tabs" role="tablist" aria-label="Benchmark track"><button role="tab" aria-selected="true" data-track="scifact">01 · Scientific retrieval</button><button role="tab" aria-selected="false" data-track="temporal">02 · Temporal filtering</button><button role="tab" aria-selected="false" data-track="lightrag">03 · LightRAG integration</button></nav><div id="content" role="tabpanel" aria-label="Selected benchmark results"></div><noscript><div class="notice">JavaScript is required for the interactive tables. Raw measurements remain available in <a href="scifact-results.json">SciFact JSON</a>, <a href="temporal-results.json">temporal JSON</a>, and <a href="lightrag-results.json">LightRAG JSON</a>.</div></noscript><footer class="footer"><span>Relevance ≠ truth. Retrieved context ≠ a generated answer.</span><span>Different tracks use different protocols. Do not compare their latency as one race.</span></footer></main><script type="application/json" id="benchmark-data">''' + payload + '''</script><script>''' + JS + '''</script></body></html>\n'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--input-dir', type=Path, default=ROOT / 'docs/benchmarks')
    parser.add_argument('--output', type=Path, default=ROOT / 'docs/benchmarks/index.html')
    parser.add_argument('--fixture', type=Path, default=ROOT / 'benchmarks/data/temporal-v1.json')
    parser.add_argument('--scifact-data', type=Path, default=ROOT / '.benchmark-data/scifact')
    args = parser.parse_args()
    data = collect_data(args.input_dir, args.fixture, args.scifact_data)
    document = render(data)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(document)
    (args.output.parent / "temporal-fixture.json").write_bytes(args.fixture.read_bytes())
    (args.output.parent / "SCIFACT-METHOD.md").write_bytes((ROOT / "benchmarks/SCIFACT-METHOD.md").read_bytes())
    print(json.dumps({'output': str(args.output), 'bytes': len(document.encode()), 'sha256': hashlib.sha256(document.encode()).hexdigest(), 'lightrag': 'present' if data['lightrag'] else 'pending'}))


if __name__ == '__main__':
    main()
